/* Lecture 4: figures and explainer */
(function () {
  const { C, ease: E, lerp, clamp } = Book;
  const rng = (seed) => () => ((seed = (seed * 16807) % 2147483647) - 1) / 2147483646;

  /* ---------- sigma-algebra generated by intervals ---------- */
  Book.viz("sigma-gen", (fig, api) => {
    const g = api.canvas(900, 470);
    let third = false;
    const gens = [[0, 0.5, "[0, 1/2]"], [0.75, 1, "[3/4, 1]"], [0.3, 0.9, "[0.3, 0.9]"]];
    const out = api.readout("");
    function draw() {
      const G = third ? gens : gens.slice(0, 2);
      g.clear(); g.view(0, 1, 0, 1, 170, 860, 10, 460);
      // breakpoints and atoms
      const bp = [...new Set([0, 1, ...G.flatMap((x) => [x[0], x[1]])])].sort((a, b) => a - b);
      const pieces = [];
      for (let i = 0; i + 1 < bp.length; i++) { const m = (bp[i] + bp[i + 1]) / 2; pieces.push([bp[i], bp[i + 1], G.map((x) => (m >= x[0] && m <= x[1] ? 1 : 0)).join("")]); }
      const sigs = [...new Set(pieces.map((p) => p[2]))];
      const col = (i) => `hsl(${(i * 67 + 20) % 360},70%,60%)`;
      let y = 30;
      G.forEach((x, i) => { g.text("generator " + x[2], 20, y + 8, { size: 16, color: C.grey, font: "sans" }); g.rect(g.X(0), y, g.X(1) - g.X(0), 16, null, "rgba(138,149,165,.4)", 1); g.rect(g.X(x[0]), y, g.X(x[1]) - g.X(x[0]), 16, C.blue); y += 28; });
      y += 8;
      g.text(`atoms (${sigs.length})`, 20, y + 10, { size: 16, color: C.white, font: "sans" });
      pieces.forEach((p) => g.rect(g.X(p[0]), y, g.X(p[1]) - g.X(p[0]), 20, col(sigs.indexOf(p[2]))));
      y += 40;
      const n = sigs.length, total = 1 << n;
      g.text(`σ(𝓕): all ${total} unions of atoms`, 20, y + 4, { size: 16, color: C.white, font: "sans" });
      y += 18;
      const h = Math.min(14, (460 - y) / total - 3);
      for (let m = 0; m < total; m++) {
        g.rect(g.X(0), y, g.X(1) - g.X(0), h, null, "rgba(138,149,165,.25)", 1);
        pieces.forEach((p) => { const k = sigs.indexOf(p[2]); if (m & (1 << k)) g.rect(g.X(p[0]), y, g.X(p[1]) - g.X(p[0]), h, col(k)); });
        y += h + 3;
      }
      out.textContent = `${G.length} generators → ${n} atoms → ${total} sets`;
    }
    api.check(" add a third generator [0.3, 0.9]", false, (v) => { third = v; draw(); });
    fig.querySelector(".controls").append(out);
    draw();
  });

  /* ---------- distance layers around a closed set ---------- */
  Book.viz("layers", (fig, api) => {
    const g = api.canvas(900, 460);
    let evenOnly = false, k = 3;
    const SC = 3.2; // display scale: layer n is 1/(n+1) <= SC*dist < 1/n
    const dC = (x, y) => {
      const d1 = Math.max(0, Math.hypot(x + 0.25, y) - 0.22);
      const qx = Math.abs(x - 0.42) - 0.12, qy = Math.abs(y - 0.12) - 0.3;
      const d2 = Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) + Math.min(Math.max(qx, qy), 0);
      return Math.max(0, Math.min(d1, d2));
    };
    const off = document.createElement("canvas"); const W = 360, H = 184; off.width = W; off.height = H;
    const octx = off.getContext("2d");
    const out = api.readout("");
    function draw() {
      const img = octx.createImageData(W, H);
      for (let j = 0; j < H; j++) for (let i = 0; i < W; i++) {
        const x = -1.95 + (3.9 * i) / W, y = 1 - (2 * j) / H;
        const d = dC(x, y) * SC; let r, gg, b;
        if (d === 0) { r = 236; gg = 230; b = 226; }
        else {
          const n = d >= 1 ? 0 : Math.ceil(1 / d) - 1;
          const nn = Math.min(n, 40);
          const hue = (nn * 47 + 190) % 360;
          let [R, G, B] = hsl(hue, 0.6, 0.55);
          let a = 1;
          if (evenOnly && nn % 2 === 1) a = 0.06;
          if (nn > k) a *= 0.28;
          r = R * a + 14 * (1 - a); gg = G * a + 22 * (1 - a); b = B * a + 33 * (1 - a);
        }
        const o = (j * W + i) * 4; img.data[o] = r; img.data[o + 1] = gg; img.data[o + 2] = b; img.data[o + 3] = 255;
      }
      octx.putImageData(img, 0, 0);
      g.clear(); g.ctx.imageSmoothingEnabled = true; g.ctx.drawImage(off, 0, 0, 900, 460);
      g.text("C", 900 * (0.5 - 0.25 / 3.9) - 6, 230, { size: 26, color: C.bg, weight: 700 });
      g.text("F \\ C sliced into layers Eₙ", 20, 30, { size: 20, color: C.white, font: "sans" });
      out.textContent = `layers E₀ … E${k <= 9 ? "₀₁₂₃₄₅₆₇₈₉"[k] : "ₖ"} highlighted: all at distance ≥ 1/${k + 1} from C`;
    }
    function hsl(h, s, l) { const a = s * Math.min(l, 1 - l); const f = (n) => { const k = (n + h / 30) % 12; return 255 * (l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1))); }; return [f(0), f(8), f(4)]; }
    api.check(" even layers only", false, (v) => { evenOnly = v; draw(); });
    api.slider("k =", 0, 12, 1, k, (v) => { k = v; draw(); });
    fig.querySelector(".controls").append(out);
    draw();
  });

  /* ---------- Explainer: Carathéodory ---------- */
  const blob = (t) => { const r = 1 + 0.18 * Math.sin(3 * t + 0.5) + 0.1 * Math.cos(5 * t); return [0.95 * r * Math.cos(t), 0.75 * r * Math.sin(t)]; };
  const inBlob = (x, y) => { const t = Math.atan2(y / 0.75, x / 0.95); const [bx, by] = blob(t); return x * x + y * y <= bx * bx + by * by; };
  const knife = (y) => 0.05 + 0.18 * Math.sin(2.2 * y + 0.4);
  const dust = []; { const r = rng(99); while (dust.length < 2600) { const x = r() * 2.6 - 1.3, y = r() * 2.2 - 1.1; if (inBlob(x, y)) dust.push([x, y, r() < 0.5]); } }
  function blobPath(g, dx, clip) {
    const c = g.ctx; c.beginPath();
    for (let i = 0; i <= 200; i++) { const [x, y] = blob((i / 200) * 2 * Math.PI); const px = g.X(x + dx), py = g.Y(y); i ? c.lineTo(px, py) : c.moveTo(px, py); }
    c.closePath();
  }
  function halfPath(g, side, dx) { // region left (side=-1) or right (+1) of the knife curve
    const c = g.ctx; c.beginPath();
    const xe = side < 0 ? -3 : 3;
    c.moveTo(g.X(xe + dx), g.Y(-2)); for (let i = 0; i <= 80; i++) { const y = -2 + (4 * i) / 80; c.lineTo(g.X(knife(y) + dx), g.Y(y)); } c.lineTo(g.X(xe + dx), g.Y(2)); c.closePath();
  }
  Book.scene("caratheodory", {
    draw(g, s) {
      g.view(-2.4, 2.4, -1.35, 1.35, 40, 1240, 80, 680);
      const c = g.ctx;
      const sep = s.seg >= 1 && s.seg <= 2 ? 0.45 * E.io(s.in(1, 0, 0.35)) * (s.seg === 2 ? 1 - E.io(s.in(2, 0, 0.3)) : 1) : 0;
      if (s.seg <= 2) {
        // pieces
        [[-1, C.blue, "F ∩ A"], [1, C.orange, "F \\ A"]].forEach(([side, col, lab]) => {
          c.save(); halfPath(g, side, side * sep); c.clip(); blobPath(g, side * sep); c.fillStyle = col + "55"; c.fill(); c.lineWidth = 3; c.strokeStyle = col; c.stroke(); c.restore();
          if (s.seg >= 1) g.text(lab, g.X(side * (0.85 + sep)), g.Y(1.12), { size: 34, align: "center", color: col, alpha: s.in(1, 0.2, 0.4) });
        });
        // knife
        c.save(); c.strokeStyle = C.white; c.lineWidth = 3; c.setLineDash([10, 8]); c.beginPath();
        for (let i = 0; i <= 80; i++) { const y = -1.3 + (2.6 * i) / 80; const px = g.X(knife(y)), py = g.Y(y); i ? c.lineTo(px, py) : c.moveTo(px, py); } c.stroke(); c.restore();
        g.text("A", g.X(-2.1), g.Y(1.1), { size: 38, color: C.white, alpha: 0.8 });
        if (s.seg === 0) g.text("F", g.X(0.2), g.Y(0), { size: 44, color: C.white, alpha: s.in(0, 0.2, 0.5) });
        if (s.seg === 1) g.title("always:  μ*(F) ≤ μ*(F ∩ A) + μ*(F \\ A)", s.in(1, 0.4, 0.6));
        if (s.seg === 2) {
          // grid cover of F, split along the knife
          const h = 0.16, a = E.out(s.in(2, 0.3, 0.6));
          for (let x = -1.3; x < 1.3; x += h) for (let y = -1.1; y < 1.1; y += h) {
            const touches = [[0, 0], [h, 0], [0, h], [h, h], [h / 2, h / 2]].some(([u, v]) => inBlob(x + u, y + v));
            if (!touches) continue;
            const left = x + h / 2 < knife(y + h / 2);
            g.alpha(a * 0.9, () => g.wrect(x, x + h, y, y + h, null, left ? C.blue : C.orange, 1.5));
          }
          g.title("nice A: a cover of F splits along A at no extra cost  ⇒  =", s.in(2, 0.5, 0.7));
        }
      } else if (s.seg === 3) {
        const spread = 0.62 * E.io(s.in(3, 0.35, 0.6));
        dust.forEach(([x, y, inA]) => { const dx = inA ? -spread : spread; g.circle(g.X(x + dx), g.Y(y), 2.2, inA ? C.blue : C.orange); });
        g.title("a Vitali-type A: both pieces are dense in F", s.in(3, 0, 0.2));
        g.text("μ*(F ∩ A) = μ*(F)", g.X(-1.3), g.Y(-1.25), { size: 30, align: "center", color: C.blue, alpha: s.in(3, 0.6, 0.75) });
        g.text("μ*(F \\ A) = μ*(F)", g.X(1.3), g.Y(-1.25), { size: 30, align: "center", color: C.orange, alpha: s.in(3, 0.7, 0.85) });
        g.text("sum = 2 μ*(F)  ✗", g.W / 2, 700, { size: 32, align: "center", color: C.red, alpha: s.in(3, 0.85, 0.95) });
      } else {
        const L = [["A is μ*-measurable  ⇔", C.white], ["μ*(F) = μ*(F ∩ A) + μ*(F \\ A)  for every F", C.yellow], ["Carathéodory:  𝓜* = { measurable sets } is a σ-algebra", C.blue], ["and μ* is countably additive on 𝓜*", C.green]];
        L.forEach(([t, col], i) => g.text(t, g.W / 2, 200 + i * 100, { size: 36, align: "center", color: col, alpha: s.in(4, i * 0.2, i * 0.2 + 0.15) }));
      }
    },
  });
})();
